-- Safety-critical flags for an eye vision test request, independent of the axes.

CREATE TABLE eye_vision_test_request_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    eye_vision_test_request_grade_id UUID NOT NULL
        REFERENCES eye_vision_test_request_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'sudden-visual-loss-emergency',
            'retinal-detachment-symptoms',
            'acute-painful-red-eye',
            'suspected-giant-cell-arteritis',
            'missing-indication',
            'missing-clinical-question',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_eye_vision_test_request_grade_flag_grade_id
    ON eye_vision_test_request_grade_flag(eye_vision_test_request_grade_id);

CREATE TRIGGER trigger_eye_vision_test_request_grade_flag_updated_at
    BEFORE UPDATE ON eye_vision_test_request_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE eye_vision_test_request_grade_flag IS
