COMMENT ON COLUMN eye_vision_test_request_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN eye_vision_test_request_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN eye_vision_test_request_grade_flag.eye_vision_test_request_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN eye_vision_test_request_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-SUDDEN-VISUAL-LOSS-001).';
COMMENT ON COLUMN eye_vision_test_request_grade_flag.category IS
    'Flag category: sudden-visual-loss-emergency, retinal-detachment-symptoms, acute-painful-red-eye, suspected-giant-cell-arteritis, missing-indication, missing-clinical-question, other.';
COMMENT ON COLUMN eye_vision_test_request_grade_flag.priority IS
